using CashBoard.Api.Models;
using Microsoft.EntityFrameworkCore;
namespace CashBoard.Api.Data; public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options) { public DbSet<Family> Families => Set<Family>(); public DbSet<User> Users => Set<User>(); public DbSet<Category> Categories => Set<Category>(); public DbSet<Transaction> Transactions => Set<Transaction>(); public DbSet<Budget> Budgets => Set<Budget>(); public DbSet<SavingsGoal> SavingsGoals => Set<SavingsGoal>(); public DbSet<Debt> Debts => Set<Debt>(); protected override void OnModelCreating(ModelBuilder b) { b.Entity<User>().HasIndex(x => x.Email).IsUnique(); b.Entity<Transaction>().Property(x => x.Amount).HasPrecision(18, 2); b.Entity<Budget>().Property(x => x.Limit).HasPrecision(18, 2); } }
